import { useState } from "react";
import { useNavigate } from "react-router-dom";
import { mockObservations } from "../mock/observations";

function ObservationsListPage() {
  const navigate = useNavigate();

  // локальний стан списку
  const [observations, setObservations] = useState(mockObservations);

  // стан видалення
  const [observationToDelete, setObservationToDelete] = useState(null);
  const [deleteError, setDeleteError] = useState(null);

  // toast
  const [toastMessage, setToastMessage] = useState(null);

  // імітація DELETE API
  const handleDelete = () => {
    try {
      setObservations((prev) =>
        prev.filter((obs) => obs.id !== observationToDelete.id)
      );

      setObservationToDelete(null);
      setDeleteError(null);

      setToastMessage("Сутність успішно видалена");
      setTimeout(() => setToastMessage(null), 3000);
    } catch (e) {
      setDeleteError("Помилка при видаленні сутності");
    }
  };

  return (
    <div style={{ padding: "24px", maxWidth: "900px", margin: "0 auto" }}>
      {/* Заголовок */}
      <h1>Список астрономічних спостережень</h1>

      {/* Кнопка додавання */}
      <div style={{ marginBottom: "20px" }}>
        <button onClick={() => navigate("/observations/new")}>
          Додати сутність
        </button>
      </div>

      {/* Список */}
      {observations.length === 0 ? (
        <p>Список спостережень порожній</p>
      ) : (
        <ul style={{ listStyle: "none", padding: 0 }}>
          {observations.map((obs) => (
            <li
              key={obs.id}
              onClick={() => navigate(`/observations/${obs.id}`)}
              style={{
                padding: "16px",
                border: "1px solid #ddd",
                borderRadius: "8px",
                marginBottom: "12px",
                cursor: "pointer",
                position: "relative",
                transition: "background-color 0.2s ease",
              }}
              onMouseEnter={(e) =>
                (e.currentTarget.style.backgroundColor = "#f9f9f9")
              }
              onMouseLeave={(e) =>
                (e.currentTarget.style.backgroundColor = "transparent")
              }
            >
              {/* Delete button (hover) */}
              <button
                style={{
                  position: "absolute",
                  right: "12px",
                  top: "12px",
                  display: "none",
                }}
                className="delete-btn"
                onClick={(e) => {
                  e.stopPropagation();
                  setObservationToDelete(obs);
                }}
                onMouseEnter={(e) =>
                  (e.currentTarget.style.display = "block")
                }
              >
                🗑
              </button>

              {/* Назва */}
              <h3 style={{ margin: "0 0 8px 0" }}>{obs.name}</h3>

              {/* Основні поля */}
              <div style={{ fontSize: "14px", color: "#555" }}>
                <div>
                  <strong>Дата спостереження:</strong>{" "}
                  {new Date(obs.observationTime).toLocaleString()}
                </div>

                <div>
                  <strong>Автор:</strong>{" "}
                  {obs.author.firstName} {obs.author.lastName}
                </div>
              </div>
            </li>
          ))}
        </ul>
      )}

      {/* Confirm modal */}
      {observationToDelete && (
        <div
          style={{
            position: "fixed",
            inset: 0,
            backgroundColor: "rgba(0,0,0,0.4)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
          }}
        >
          <div
            style={{
              background: "#fff",
              padding: "24px",
              borderRadius: "8px",
              width: "400px",
            }}
          >
            <h3>Підтвердження видалення</h3>

            <p>
              Ви впевнені, що хочете видалити{" "}
              <strong>{observationToDelete.name}</strong>?
            </p>

            {deleteError && (
              <p style={{ color: "red" }}>{deleteError}</p>
            )}

            <div
              style={{
                display: "flex",
                justifyContent: "flex-end",
                gap: "8px",
                marginTop: "16px",
              }}
            >
              <button onClick={() => setObservationToDelete(null)}>
                Скасувати
              </button>
              <button onClick={handleDelete}>Видалити</button>
            </div>
          </div>
        </div>
      )}

      {/* Toast */}
      {toastMessage && (
        <div
          style={{
            position: "fixed",
            bottom: "20px",
            right: "20px",
            background: "#333",
            color: "#fff",
            padding: "12px 16px",
            borderRadius: "6px",
          }}
        >
          {toastMessage}
        </div>
      )}
    </div>
  );
}

export default ObservationsListPage;
